import React, { useState, useEffect, useRef } from 'react';
import './Cards.css';
import LanguagesConnections from '../../wordLibrary/LanguagesConnections.json';
import WordsCategory from '../../wordLibrary/wordsParams/WordsCategory.json';
import WordsPos from '../../wordLibrary/wordsParams/WordsPos.json';
import WordsLvl from '../../wordLibrary/wordsParams/WordsLvl.json';
import WordsSection from '../../wordLibrary/wordsParams/WordsSection.json';
import WordsType from '../../wordLibrary/wordsParams/WordsType.json';
import { t } from '../../i18n';
import { loadLanguageTable } from '../../utils/availableLanguages';
import { getLanguageCssVars } from '../ColorsMap';

const Cards = ({ setCardsMode, setCardsMenuMode, cardsFilter, selectedCardThemes, selectedCardTypes, uiLang, nativeLang, learningLang }) => {
  const [currentCardIndex, setCurrentCardIndex] = useState(0);
  const [isFlipped, setIsFlipped] = useState(false);
  const [cards, setCards] = useState([]);
  const [cardsTotal, setCardsTotal] = useState(0);
  const [userTable, setUserTable] = useState([]);
  const [nativeTable, setNativeTable] = useState([]);
  const [learningTable, setLearningTable] = useState([]);
  const [dragX, setDragX] = useState(0);
  const [isRemoving, setIsRemoving] = useState(false);
  const [removeDir, setRemoveDir] = useState(0);
  const dragState = useRef({ dragging: false, startX: 0 });
  const builtSessionKeyRef = useRef('');

  useEffect(() => {
    // Обработчик для отмены свайпа по нажатию ESC
    const handleKeyDown = (e) => {
      if (e.key === 'Escape' && dragState.current.dragging) {
        // сбрасываем свайп
        setDragX(0);
        dragState.current = { dragging: false, startX: 0 };
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => {
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, []);

  const getCurrentUser = () => {
    return localStorage.getItem('currentUser') || 'default';
  };

  const API_URL = 'http://localhost:5000/api/user-table';
  const resolvedLearningLang = learningLang || 'ES';
  const resolvedNativeLang = nativeLang || uiLang || 'ES';
  const currentUser = getCurrentUser();
  const themesKey = (selectedCardThemes || []).slice().sort().join('|');
  const typesKey = (selectedCardTypes || []).slice().sort().join('|');
  const sessionKey = `${resolvedLearningLang}|${resolvedNativeLang}|${currentUser}|${cardsFilter || 'mix'}|${themesKey}|${typesKey}`;
  const themeVars = getLanguageCssVars(resolvedLearningLang);
  const languageIdFieldByLang = {
    EN: 'EN_id',
    DE: 'DE_id',
    ES: 'ES_id',
    RU: 'RU_id'
  };
  const learningIdField = languageIdFieldByLang[resolvedLearningLang] || 'ES_id';
  const nativeIdField = languageIdFieldByLang[resolvedNativeLang] || 'ES_id';
  const connections = LanguagesConnections?.LanguagesConnections || [];
  const categoryById = new Map((WordsCategory?.WordsCategory || []).map(item => [Number(item.CAT_id), item.category]));
  const posById = new Map((WordsPos?.WordsPos || []).map(item => [Number(item.WP_id), item.pos]));
  const lvlById = new Map((WordsLvl?.WordsLvl || []).map(item => [Number(item.WL_id), item.lengLvl]));
  const sectionById = new Map((WordsSection?.WordsSection || []).map(item => [Number(item.WS_id), item.section]));
  const typeById = new Map((WordsType?.WordsType || []).map(item => [Number(item.WT_id), item.type]));
  const metaByLearningId = new Map();
  connections.forEach(conn => {
    const learningId = Number(conn[learningIdField]);
    if (Number.isNaN(learningId) || metaByLearningId.has(learningId)) return;
    metaByLearningId.set(learningId, {
      category: categoryById.get(Number(conn.CAT_id)) || 'Other',
      pos: posById.get(Number(conn.WP_id)) || 'Other',
      lengLvl: lvlById.get(Number(conn.WL_id)) || null,
      section: Number(sectionById.get(Number(conn.WS_id))) || 1,
      type: typeById.get(Number(conn.WT_id)) || null
    });
  });

  useEffect(() => {
    let isActive = true;
    const loadTables = async () => {
      const [nativeData, learningData] = await Promise.all([
        loadLanguageTable(resolvedNativeLang),
        loadLanguageTable(resolvedLearningLang)
      ]);
      if (!isActive) return;
      setNativeTable(nativeData);
      setLearningTable(learningData);
    };
    loadTables();
    return () => {
      isActive = false;
    };
  }, [resolvedNativeLang, resolvedLearningLang]);

  useEffect(() => {
    const loadUserTable = async () => {
      if (!learningTable || learningTable.length === 0) return;
      try {
        let serverData = [];
        const response = await fetch(`${API_URL}/${currentUser}/${resolvedLearningLang}`);
        serverData = await response.json();

        // Получаем свежие данные из JSON
        const freshData = (learningTable || []).map(item => {
          const learningId = Number(item[learningIdField]);
          const meta = metaByLearningId.get(learningId) || {};
          return {
            ...item,
            section: Number(item.section) || Number(meta.section) || 1,
            sectionHistory: []
          };
        });

        if (serverData.length > 0) {
          setUserTable(serverData);
        } else {
          setUserTable(freshData);
          await saveUserTable(freshData);
        }
      } catch (error) {
        console.error('Ошибка при загрузке таблицы:', error);
        setUserTable((learningTable || []).map(item => {
          const learningId = Number(item[learningIdField]);
          const meta = metaByLearningId.get(learningId) || {};
          return {
            ...item,
            section: Number(item.section) || Number(meta.section) || 1,
            sectionHistory: []
          };
        }));
      }
    };
    loadUserTable();
  }, [learningTable, resolvedLearningLang, learningIdField, currentUser]);

  const saveUserTable = async (data) => {
    const user = getCurrentUser();
    try {
      await fetch(`${API_URL}/${user}/${resolvedLearningLang}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(data)
      });
    } catch (error) {
      console.error('Ошибка при сохранении таблицы:', error);
    }
  };

  useEffect(() => {
    builtSessionKeyRef.current = '';
    setCards([]);
    setCurrentCardIndex(0);
    setCardsTotal(0);
  }, [sessionKey]);

  useEffect(() => {
    if (!userTable || userTable.length === 0) return;
    if (!nativeTable || nativeTable.length === 0) return;
    if (builtSessionKeyRef.current === sessionKey) return;

    if (!userTable || userTable.length === 0) return;
    const learningById = new Map((userTable || []).map(item => [Number(item[learningIdField]), item]));
    const nativeById = new Map((nativeTable || []).map(item => [Number(item[nativeIdField]), item]));
    const cardsData = connections.map(conn => {
      const learningId = Number(conn[learningIdField]);
      const nativeId = Number(conn[nativeIdField]);
      if (Number.isNaN(learningId) || Number.isNaN(nativeId)) return null;
      const learningWord = learningById.get(learningId);
      const nativeWord = nativeById.get(nativeId);
      const meta = metaByLearningId.get(learningId) || {};
      return {
        id: `${learningId}-${nativeId}`,
        learning: learningWord
          ? {
            ...learningWord,
            category: meta.category || learningWord.category || 'Other',
            pos: meta.pos || learningWord.pos || 'Other',
            type: meta.type || learningWord.type || null,
            lengLvl: meta.lengLvl || learningWord.lengLvl || null,
            section: Number(learningWord.section) || Number(meta.section) || 1
          }
          : null,
        native: nativeWord || null
      };
    }).filter(card => card && card.learning && card.native);

    const mode = cardsFilter || 'mix';
    const themeFilter = selectedCardThemes && selectedCardThemes.length > 0 ? selectedCardThemes : null;
    const typeFilter = selectedCardTypes && selectedCardTypes.length > 0 ? selectedCardTypes : null;
    
    const filtered = cardsData.filter(card => {
      const section = Number(card.learning.section) || 1;
      const category = card.learning.category || 'Other';
      const wordType = card.learning.pos || 'Other';
      
      // Фильтр по режиму
      if (mode === 'repeat' && ![5, 4, 3].includes(section)) return false;
      if (mode === 'learn' && ![3, 2, 1].includes(section)) return false;
      
      // Фильтр по темам (если выбраны)
      if (themeFilter && !themeFilter.includes(category)) return false;

      // Фильтр по типам (если выбраны)
      if (typeFilter && !typeFilter.includes(wordType)) return false;
      
      return true;
    });

    const uniqueByLearning = [];
    const usedLearningIds = new Set();
    filtered.forEach(card => {
      const learningId = Number(card.learning[learningIdField]);
      if (Number.isNaN(learningId) || usedLearningIds.has(learningId)) return;
      usedLearningIds.add(learningId);
      uniqueByLearning.push(card);
    });

    // Перемешиваем карточки для случайного порядка
    const shuffled = [...uniqueByLearning];
    for (let i = shuffled.length - 1; i > 0; i -= 1) {
      const j = Math.floor(Math.random() * (i + 1));
      [shuffled[i], shuffled[j]] = [shuffled[j], shuffled[i]];
    }

    builtSessionKeyRef.current = sessionKey;
    setCards(shuffled);
    setCardsTotal(shuffled.length);
  }, [userTable, nativeTable, cardsFilter, selectedCardThemes, selectedCardTypes, learningIdField, nativeIdField, sessionKey]);

  useEffect(() => {
    setCurrentCardIndex(0);
  }, [cardsFilter, selectedCardThemes, selectedCardTypes]);

  const handleFinishCards = () => {
    setCardsMode(false);
    setCardsMenuMode(true);
  };

  const handleCardClick = () => {
    setIsFlipped(!isFlipped);
  };

  const handleNextCard = () => {
    setIsFlipped(false);
    if (cards.length === 0) return;
    if (currentCardIndex + 1 >= cards.length) {
      handleFinishCards();
      return;
    }
    setCurrentCardIndex((prevIndex) => prevIndex + 1);
  };

  const handlePrevCard = () => {
    setIsFlipped(false);
    if (cards.length === 0) return;
    setCurrentCardIndex((prevIndex) => Math.max(0, prevIndex - 1));
  };

  // Обновление section и сохранение на сервер
  const updateSectionForLearning = (learningId, isCorrect) => {
    setUserTable(prev => {
      const next = prev.map(item => {
        if (Number(item[learningIdField]) === Number(learningId)) {
          const current = Number(item.section) || 1;
          let nextSection = current;
          if (isCorrect) nextSection = Math.min(5, current + 1);
          else nextSection = Math.max(1, current - 1);
          return { ...item, section: nextSection, sectionHistory: [...(item.sectionHistory||[]), { at: Date.now(), from: current, to: nextSection, correct: !!isCorrect }] };
        }
        return item;
      });
      // Сохраняем на сервер
      saveUserTable(next);
      return next;
    });
  };

  // --- Drag / swipe handlers ---
  const onPointerDown = (clientX) => {
    dragState.current = { dragging: true, startX: clientX };
  };

  const onPointerMove = (clientX) => {
    if (!dragState.current.dragging) return;
    const dx = clientX - dragState.current.startX;
    setDragX(dx);
  };

  const finishDrag = () => {
    const threshold = 120;
    const dx = dragX;
    if (Math.abs(dx) > threshold) {
      const isRight = dx > 0;
      // сбрасываем переворот и помечаем карточку на удаление
      setIsFlipped(false);
      setRemoveDir(isRight ? 1 : -1);
      setIsRemoving(true);
      // обновляем section сразу
      updateSectionForLearning(currentCard.learning[learningIdField], isRight);

      // через анимацию переключаем карточку
      setTimeout(() => {
        setIsRemoving(false);
        setDragX(0);
        setCurrentCardIndex((prev) => {
          const nextIndex = prev + 1;
          if (nextIndex >= cards.length) {
            handleFinishCards();
            return prev;
          }
          return nextIndex;
        });
      }, 300);
    } else {
      // недостаточно — сбрасываем позицию
      setDragX(0);
    }

    dragState.current = { dragging: false, startX: 0 };
  };

  const handleMouseDown = (e) => onPointerDown(e.clientX);
  const handleMouseMove = (e) => onPointerMove(e.clientX);
  const handleMouseUp = () => finishDrag();

  const handleTouchStart = (e) => onPointerDown(e.touches[0].clientX);
  const handleTouchMove = (e) => onPointerMove(e.touches[0].clientX);
  const handleTouchEnd = () => finishDrag();

  if (cards.length === 0) {
    return (
      <div className="cards-container">
        <button
          className="back-button"
          onClick={() => {
            setCardsMode(false);
            setCardsMenuMode(true);
          }}
        >
          {t('back', uiLang)}
        </button>
        <h1>{t('cardsLoading', uiLang)}</h1>
      </div>
    );
  }

  const currentCard = cards[currentCardIndex];

  return (
    <div className="cards-container" style={themeVars}>
      <button
        className="back-button"
        onClick={() => {
          setCardsMode(false);
          setCardsMenuMode(true);
        }}
      >
        {t('back', uiLang)}
      </button>
      
      {/* Боксы для левого и правого свайпа */}
      <div className="swipe-box swipe-box-left" style={{
        opacity: dragX < 0 ? Math.min(1, Math.abs(dragX) / 200) : 0
      }} />
      <div className="swipe-box swipe-box-right" style={{
        opacity: dragX > 0 ? Math.min(1, Math.abs(dragX) / 200) : 0
      }} />
      
      <div className="cards-wrapper">        
        <div className="card-area">
          <div className={`card ${isFlipped ? 'flipped' : ''}`}
            onMouseDown={handleMouseDown}
            onMouseMove={handleMouseMove}
            onMouseUp={handleMouseUp}
            onTouchStart={handleTouchStart}
            onTouchMove={handleTouchMove}
            onTouchEnd={handleTouchEnd}
            onClick={() => { if (Math.abs(dragX) < 10 && !isRemoving) handleCardClick(); }}
            style={{
              transform: isRemoving ? `translateX(${removeDir * 1200}px) rotate(${removeDir * 30}deg)` : `translateX(${dragX}px) rotate(${dragX / 20}deg)`,
              opacity: isRemoving ? 0 : 1,
              transition: isRemoving ? 'transform 0.3s ease, opacity 0.3s ease' : undefined,
              pointerEvents: isRemoving ? 'none' : 'auto'
            }}
          >
            <div className="card-inner">
            {/* Передняя сторона - слово на learning (немецкий) */}
            <div className="card-front">
              <div className="card-section">{currentCard.learning.section}</div>
              <div className="card-word">{currentCard.native.word}</div>
              <div className="card-level">{currentCard.learning.lengLvl}</div>
              <div className="card-hint">{t('tapForTranslation', uiLang)}</div>
            </div>

            {/* Задняя сторона - слово на native (испанский) */}
            <div className="card-back">
              <div className="card-section card-section-back">{currentCard.learning.section}</div>
              <div className="card-back-content">
                <div className="card-translation">{currentCard.learning.word}</div>
                <div className="card-transcription">{currentCard.learning.transcription}</div>
                <div className="card-example">
                  <span className="example-label">{t('exampleLabel', uiLang)}</span>
                  <span className="example-text">{currentCard.learning.example}</span>
                </div>
              </div>
            </div>
          </div>
          </div>

        </div>
      </div>

      <div className="cards-counter">
        {currentCardIndex + 1} / {cardsTotal || cards.length}
      </div>
    </div>
  );
};

export default Cards;
