import React, { useState, useRef, useEffect, useMemo } from 'react';
import { t } from '../i18n';
import { loadAvailableLanguageIds } from '../utils/availableLanguages';

const LANGUAGES = [
  { id: 'FR', name: 'Français' },
  { id: 'EN', name: 'English' },
  { id: 'ES', name: 'Español' },
  { id: 'DE', name: 'Deutsch' },
  { id: 'RU', name: 'Русский' },
  { id: 'JA', name: '日本語' },
  { id: 'ZH', name: '中文' },
  { id: 'IT', name: 'Italiano' },
  { id: 'PT', name: 'Português' },
  { id: 'KO', name: '한국어' },
];
const StartChoosingLanguages = ({ setLanguages, setShowMainMenu, uiLang }) => {
  const [selectedLanguageId, setSelectedLanguageId] = useState(LANGUAGES[0].id);
  const [isSelected, setIsSelected] = useState(false);
  const [availableLanguageIds, setAvailableLanguageIds] = useState(() => new Set());
  const scrollRef = useRef(null);
  const isDragging = useRef(false);
  const startY = useRef(0);
  const startScrollTop = useRef(0);
  const selectNativeText = t('selectNative', uiLang);
  const selectLearnigText = t('selectLearning', uiLang);
  const nativeLanguageId = uiLang;

  useEffect(() => {
    const loadLanguages = async () => {
      const ids = await loadAvailableLanguageIds(LANGUAGES.map(lang => lang.id));
      setAvailableLanguageIds(new Set(ids));
    };
    loadLanguages();
  }, []);

  const visibleLanguages = useMemo(() => {
    if (isSelected && nativeLanguageId) {
      return LANGUAGES.filter(lang => lang.id !== nativeLanguageId);
    }
    return LANGUAGES;
  }, [isSelected, nativeLanguageId]);

  const data = useMemo(() => (
    [...visibleLanguages, ...visibleLanguages, ...visibleLanguages, ...visibleLanguages, ...visibleLanguages]
  ), [visibleLanguages]);

  const itemHeight = 50;
  const SCROLL_SPEED = 0.1; // Меньше -> медленнее прокрутка

  useEffect(() => {
    if (scrollRef.current) {
      // Устанавливаем скролл в середину общего массива
      scrollRef.current.scrollTop = visibleLanguages.length * itemHeight * 2;
    }
  }, [visibleLanguages.length]);

  const handleScroll = () => {
    const container = scrollRef.current;
    if (!container) return;

    const scrollTop = container.scrollTop;
    const singleSetHeight = visibleLanguages.length * itemHeight;

    // Бесшовный переход
    if (scrollTop < singleSetHeight) {
      container.scrollTop = scrollTop + singleSetHeight;
    } else if (scrollTop > singleSetHeight * 3) {
      container.scrollTop = scrollTop - singleSetHeight;
    }

    // Вычисляем индекс по центру контейнера (надёжнее при наличии маски)
    const centerY = scrollTop + (container.clientHeight / 2);
    // Смещаем на половину высоты элемента, чтобы округление попадало на центр элемента
    const rawIndex = Math.round((centerY - itemHeight / 2) / itemHeight);
    const index = ((rawIndex % visibleLanguages.length) + visibleLanguages.length) % visibleLanguages.length;
    setSelectedLanguageId(visibleLanguages[index].id);
  };

  // --- Логика перетаскивания мышью (ЛКМ) ---
  const onMouseDown = (e) => {
    isDragging.current = true;
    startY.current = e.pageY;
    startScrollTop.current = scrollRef.current.scrollTop;
    scrollRef.current.style.scrollSnapType = 'none'; // Отключаем snap пока тянем
    scrollRef.current.style.cursor = 'grabbing';
  };

  const onMouseMove = (e) => {
    if (!isDragging.current) return;
    e.preventDefault();
    const y = e.pageY;
    const walk = (y - startY.current) // * SCROLL_SPEED; // Коэффициент скорости
    scrollRef.current.scrollTop = startScrollTop.current - walk;
  };

  const onWheel = (e) => {
    // Контролируем скорость скролла колесом мыши
    e.preventDefault();
    if (!scrollRef.current) return;
    scrollRef.current.scrollTop += e.deltaY * SCROLL_SPEED;
  };

  const onMouseUp = () => {
    isDragging.current = false;
    if (scrollRef.current) {
      scrollRef.current.style.scrollSnapType = 'y mandatory'; // Возвращаем snap
      scrollRef.current.style.cursor = 'grab';
    }
  };

  const handleMaskClick = () => {
    // Логика при нажатии на маску
    const currentLanguage = LANGUAGES.find(lang => lang.id === selectedLanguageId);
    console.log('Selected language:', currentLanguage);
    // Здесь будет дальнейшая логика
  };

  const isLanguageAvailable = (languageId) => availableLanguageIds.has(languageId);

  const handleArrowClick = () => {
    const currentLanguage = LANGUAGES.find(lang => lang.id === selectedLanguageId);
    if (currentLanguage) {
      if (!isLanguageAvailable(currentLanguage.id)) {
        return;
      }
      if (!isSelected) {
        // Первый клик: выбрать родной язык
        setLanguages(prev => ({ ...prev, native: currentLanguage.id }));
        setIsSelected(true);
        console.log('Native language selected:', currentLanguage.id);
      } else {
        // Второй клик: выбрать язык для изучения и закрыть панель
        if (currentLanguage.id === nativeLanguageId) {
          return;
        }
        setLanguages(prev => {
          const learning = Array.isArray(prev.learning) ? prev.learning : (prev.learning ? [prev.learning] : []);
          const nextLearning = learning.includes(currentLanguage.id)
            ? learning
            : [...learning, currentLanguage.id];
          return { ...prev, learning: nextLearning };
        });
        console.log('Learning language selected:', currentLanguage.id);
        setShowMainMenu(true);
      }
    }
  };

  return (
  <>
    <div className="picker-image" data-selected={isSelected}>
      <img src={isSelected ? "./img/espBird.png" : "./img/engBird.png"} alt={t('languageBirdAlt', uiLang)} />

      <svg
        viewBox="0 0 600 90"
        xmlns="http://www.w3.org/2000/svg"
        className="bubble"
      >
        <path
          d="M10 10 H590 A10 10 0 0 1 600 20 V60
             A10 10 0 0 1 590 70 H90
             L60 90 L65 70 H10
             A10 10 0 0 1 0 60 V20
             A10 10 0 0 1 10 10 Z"
        />
      </svg>

      <span className="dialog-text">
        {isSelected ? selectLearnigText : selectNativeText}
      </span>
    </div>

    <div className="picker-row">
      <div className="picker-wrapper" data-selected={isSelected}>
        <div
          className="picker-selection-mask"
          onClick={handleMaskClick}
        />

        <div
          className="picker-container"
          ref={scrollRef}
          onScroll={handleScroll}
          onWheel={onWheel}
          onMouseDown={onMouseDown}
          onMouseMove={onMouseMove}
          onMouseUp={onMouseUp}
          onMouseLeave={onMouseUp}
          style={{ cursor: 'grab' }}
        >
          <div className="picker-list">
            {data.map((lang, index) => (
              <div
                key={index}
                className={`picker-item ${
                  selectedLanguageId === lang.id
                    ? 'picker-item--selected'
                    : ''
                } ${!isLanguageAvailable(lang.id) ? 'picker-item--locked' : ''}`}
              >
                <span className="picker-item-text">{lang.name}</span>
                {!isLanguageAvailable(lang.id) && (
                  <span className="picker-item-lock">🔒</span>
                )}
              </div>
            ))}
          </div>
        </div>
      </div>

      <button className="arrow-btn" onClick={handleArrowClick} data-selected={isSelected}>
        <svg
          width="48"
          height="48"
          viewBox="0 0 48 48"
          xmlns="http://www.w3.org/2000/svg"
        >
          <circle cx="24" cy="24" r="23" />
          <path
            d="M20 16 L28 24 L20 32"
            fill="none"
            strokeWidth="3"
            strokeLinecap="round"
            strokeLinejoin="round"
          />
        </svg>
      </button>
    </div>
  </>
);

};

export default StartChoosingLanguages;